"""Interactive Folium map for one trip, generated by the REAL pipeline (not a hand-made figure).

Layers (toggle with the layer control, top right):
  - Raw GPS observations            (orange dots, popup = point index + timestamp)
  - Road network around the trip    (grey)
  - Reference route                 (green)   <- offline analysis only, uses the .route file
  - Predicted route, classifier+HMM (blue)
  - Predicted route, classifier only (red, hidden by default) to show where the HMM changed things

This is a development/report tool for the training and student-test partitions. The reference route is
read here only to draw it; it is never given to the pipeline, and the API never returns it.

Usage:
  python scripts/folium_prediction_map.py <trip_dir> <out.html> [--start N --end M]
  e.g. python scripts/folium_prediction_map.py "../Student folder/student_test/00000000" maps/student_00000000.html
"""
import argparse
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

import folium
import numpy as np
from scipy.spatial import cKDTree

from pathsnap.data import load_trip
from pathsnap.pipeline import TrainedPipeline

ROOT = os.path.join(os.path.dirname(__file__), "..")
MAX_ROAD_ARCS = 6000          # keeps the HTML light; arcs nearest to the GPS track are kept


def seg(trip_nodes, arcs, a):
    f, t = arcs[a]
    return [[float(trip_nodes[f][1]), float(trip_nodes[f][0])], [float(trip_nodes[t][1]), float(trip_nodes[t][0])]]


def arc_layer(name, nodes, arcs, arc_ids, color, weight, show=True, dash=None):
    g = folium.FeatureGroup(name, show=show)
    seen = set()
    for a in arc_ids:
        a = int(a)
        if a < 0 or a in seen:
            continue
        seen.add(a)
        folium.PolyLine(seg(nodes, arcs, a), color=color, weight=weight, opacity=0.85, dash_array=dash,
                        tooltip=f"arc {a}").add_to(g)
    return g, len(seen)


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("trip_dir")
    ap.add_argument("out_html")
    ap.add_argument("--model", default=os.path.join(ROOT, "artifacts", "candidate_model.joblib"))
    ap.add_argument("--config", default=os.path.join(ROOT, "artifacts", "model_config.json"))
    ap.add_argument("--start", type=int, default=0, help="first GPS point to show (zoom into a section)")
    ap.add_argument("--end", type=int, default=0, help="last GPS point to show (0 = all)")
    args = ap.parse_args()

    trip = load_trip(args.trip_dir, with_route=True)
    pipe = TrainedPipeline(args.model, args.config)
    pred = pipe.predict(trip.track, trip.nodes, trip.arcs)           # the route is NOT passed in

    n = len(trip.track)
    lo, hi = args.start, (args.end or n)
    idx = np.arange(lo, hi)
    gps = trip.track[idx]
    hmm, top1 = pred.hmm_arcs.to_numpy()[idx], pred.classifier_arcs.to_numpy()[idx]

    m = folium.Map(location=[float(gps[:, 1].mean()), float(gps[:, 0].mean())], zoom_start=15, tiles="OpenStreetMap")
    m.fit_bounds([[float(gps[:, 1].min()), float(gps[:, 0].min())], [float(gps[:, 1].max()), float(gps[:, 0].max())]])

    # road network: the arcs whose midpoints are closest to the displayed GPS points
    mids = (trip.nodes[trip.arcs[:, 0]] + trip.nodes[trip.arcs[:, 1]]) / 2
    d, _ = cKDTree(gps[:, :2]).query(mids)
    roads = np.argsort(d)[:MAX_ROAD_ARCS]
    road_layer, n_road = arc_layer("Road network (grey)", trip.nodes, trip.arcs, roads, "#888888", 2, show=True)
    ref_layer, n_ref = arc_layer("Reference route (green)", trip.nodes, trip.arcs, trip.route, "#1a9641", 6)
    hmm_layer, n_hmm = arc_layer("Predicted route: classifier + HMM (blue)", trip.nodes, trip.arcs, hmm, "#2b6cb0", 4)
    clf_layer, n_clf = arc_layer("Predicted route: classifier only (red)", trip.nodes, trip.arcs, top1, "#d7191c", 3,
                                 show=False, dash="6 6")
    gps_layer = folium.FeatureGroup("Raw GPS observations (orange)")
    for i, (lon, lat, t) in zip(idx, gps):
        folium.CircleMarker([float(lat), float(lon)], radius=2, color="#f28e2b", fill=True, fill_opacity=0.8,
                            weight=1, popup=f"point {i}, t={t:.0f}s").add_to(gps_layer)
    for layer in (road_layer, ref_layer, hmm_layer, clf_layer, gps_layer):
        layer.add_to(m)
    folium.LayerControl(collapsed=False).add_to(m)

    legend = f"""
    <div style="position: fixed; bottom: 24px; left: 24px; z-index: 9999; background: white; padding: 10px 14px;
                border: 1px solid #999; border-radius: 6px; font: 13px sans-serif; line-height: 1.6;">
      <b>Trip {trip.trip_id}</b> &middot; points {lo}-{hi - 1} of {n}<br>
      <span style="color:#f28e2b">&#9679;</span> raw GPS<br>
      <span style="color:#888">&#9473;</span> road network ({n_road} arcs)<br>
      <span style="color:#1a9641">&#9473;</span> reference route ({n_ref} arcs)<br>
      <span style="color:#2b6cb0">&#9473;</span> predicted, classifier + HMM ({n_hmm} arcs)<br>
      <span style="color:#d7191c">&#9473;</span> predicted, classifier only ({n_clf} arcs, off by default)
    </div>"""
    m.get_root().html.add_child(folium.Element(legend))

    os.makedirs(os.path.dirname(os.path.abspath(args.out_html)), exist_ok=True)
    m.save(args.out_html)
    print(f"saved {args.out_html}  (GPS {len(idx)} points, road {n_road}, reference {n_ref}, HMM {n_hmm}, classifier-only {n_clf} arcs)")


if __name__ == "__main__":
    main()
